r"""Grade 11 additions: Unit 1 law of mass action + Le Chatelier (pressure, concentration), Unit 3 carbon allotropes + carbonic
acid, Unit 4 activity series, Unit 5 ideal gas equation derivation, PM = dRT and van der Waals."""
from common import Unit

# ============================================================== Unit 1 Rate and equilibrium
U1 = Unit('chem11-u1')
L1 = '1.2 Equilibrium: mass action and Le Chatelier'
DIAG1 = {'cm_press': 'press', 'cm_conc': 'conc'}

MASS = [
    U1.T('c01', 'The law of mass action, step by step', 19,
         '**Law of mass action** (Guldberg and Waage, 1864): at constant temperature, the rate of a reaction is proportional to the product of the molar concentrations of the reactants, each raised to the power of its coefficient in the balanced equation.',
         r'**Step 1 — Write both rates** for \(a\text{A} + b\text{B} \rightleftharpoons c\text{C} + d\text{D}\):',
         r'$$\text{rate}_f = k_f[\text{A}]^a[\text{B}]^b \qquad \text{rate}_b = k_b[\text{C}]^c[\text{D}]^d$$',
         r'**Step 2 — At equilibrium the two rates are equal:** \(k_f[\text{A}]^a[\text{B}]^b = k_b[\text{C}]^c[\text{D}]^d\).',
         r'**Step 3 — Collect the constants on one side:**',
         r'$$K_c = \frac{k_f}{k_b} = \frac{[\text{C}]^c[\text{D}]^d}{[\text{A}]^a[\text{B}]^b}$$',
         '**Rules for writing Kc:** products on top, reactants below; each concentration (in mol/L) raised to its coefficient; concentrations are the **equilibrium** values. For gases you may use partial pressures instead → **Kp**. Pure solids and pure liquids are left out (their “concentration” is constant).',
         '**Kc changes only with temperature** — not with concentration, pressure or a catalyst.',
         '**Size of K:** K ≫ 1 → mostly products at equilibrium; K ≪ 1 → mostly reactants; K ≈ 1 → appreciable amounts of both.'),
    U1.T('c02', 'Reaction quotient Q: which way will it go?', 20,
         'Q is calculated exactly like K but with the concentrations **at any moment** (not necessarily at equilibrium). Compare Q with K:',
         '**Q < K** → too little product → net reaction goes **forward (to the right)**.',
         '**Q = K** → at equilibrium → no net change.',
         '**Q > K** → too much product → net reaction goes **backward (to the left)**.'),
    U1.WK('w01', 'Worked example: writing Kc expressions', 19,
          'Write Kc for (a) H₂(g) + I₂(g) ⇌ 2HI(g); (b) 2SO₂(g) + O₂(g) ⇌ 2SO₃(g); (c) N₂O₄(g) ⇌ 2NO₂(g); (d) CaCO₃(s) ⇌ CaO(s) + CO₂(g).',
          [r'(a) \(K_c = \dfrac{[\text{HI}]^2}{[\text{H}_2][\text{I}_2]}\)',
           r'(b) \(K_c = \dfrac{[\text{SO}_3]^2}{[\text{SO}_2]^2[\text{O}_2]}\)',
           r'(c) \(K_c = \dfrac{[\text{NO}_2]^2}{[\text{N}_2\text{O}_4]}\)',
           r'(d) Solids are left out: \(K_c = [\text{CO}_2]\)'],
          'Products over reactants, powers = coefficients, no solids or pure liquids.'),
    U1.WK('w02', 'Worked example: calculating Kc (textbook p.19)', 19,
          'For N₂(g) + 3H₂(g) ⇌ 2NH₃(g) at equilibrium: [N₂] = 3.0 × 10⁻² M, [H₂] = 3.7 × 10⁻² M, [NH₃] = 1.6 × 10⁻² M. Calculate Kc.',
          [r'\(K_c = \dfrac{[\text{NH}_3]^2}{[\text{N}_2][\text{H}_2]^3}\)',
           r'Top: \((1.6\times10^{-2})^2 = 2.56\times10^{-4}\)',
           r'Bottom: \((3.0\times10^{-2})(3.7\times10^{-2})^3 = (3.0\times10^{-2})(5.07\times10^{-5}) = 1.52\times10^{-6}\)',
           r'\(K_c = \dfrac{2.56\times10^{-4}}{1.52\times10^{-6}} = 1.68\times10^{2}\)'],
          'Kc = 1.68 × 10²'),
    U1.WK('w03', 'Worked example: finding an equilibrium concentration', 20,
          'Same reaction, same temperature (Kc = 1.68 × 10²). At equilibrium [N₂] = 6.0 × 10⁻² M and [H₂] = 5.6 × 10⁻² M. Find [NH₃].',
          [r'Let \([\text{NH}_3] = x\): \(1.68\times10^{2} = \dfrac{x^2}{(6.0\times10^{-2})(5.6\times10^{-2})^3}\)',
           r'Bottom: \((6.0\times10^{-2})(1.76\times10^{-4}) = 1.05\times10^{-5}\)',
           r'\(x^2 = 1.68\times10^{2} \times 1.05\times10^{-5} = 1.77\times10^{-3}\)',
           r'\(x = \sqrt{1.77\times10^{-3}} = 4.21\times10^{-2}\text{ M}\)'],
          '[NH₃] = 4.21 × 10⁻² M'),
    U1.WK('w04', 'Worked example: Q vs K (textbook p.21)', 21,
          'For N₂ + 3H₂ ⇌ 2NH₃, Kc = 1.7 × 10². A mixture has [N₂] = 2.0 × 10⁻² M, [H₂] = 3.5 × 10⁻² M, [NH₃] = 2.0 × 10⁻² M. Is it at equilibrium? If not, which way does it shift?',
          [r'\(Q_c = \dfrac{(2.0\times10^{-2})^2}{(2.0\times10^{-2})(3.5\times10^{-2})^3} = \dfrac{4.00\times10^{-4}}{8.58\times10^{-7}}\)',
           r'\(Q_c = 4.66\times10^{2}\)', 'Qc (466) > Kc (170): too much product.', 'Net reaction goes to the **left**: some NH₃ decomposes until Q = K.'],
          'Not at equilibrium; shifts left.'),
    U1.CK('k01', 19, 'For 2NO(g) + O₂(g) ⇌ 2NO₂(g), Kc = …',
          ['[NO₂]/([NO][O₂])', '[NO₂]²/([NO]²[O₂])', '[NO]²[O₂]/[NO₂]²', '2[NO₂]/(2[NO][O₂])'], 'B',
          'Products over reactants, each raised to its coefficient: [NO₂]² over [NO]²[O₂].'),
    U1.CK('k02', 20, 'If Q > K for a reaction mixture, the reaction will …',
          ['shift right', 'shift left', 'stay the same', 'stop'], 'B',
          'Q > K means there is more product than at equilibrium, so the backward reaction wins until Q falls to K.'),
]

CHAT = [
    U1.T('c03', 'Le Chatelier’s principle, step by step', 22,
         '**Le Chatelier’s principle:** if a stress is applied to a system at equilibrium, the system shifts so as to **reduce (oppose) the stress** and reaches a new equilibrium position.',
         '**Step 1 — Name the stress:** more or less of a substance (concentration), higher or lower pressure (volume), higher or lower temperature.',
         '**Step 2 — Ask how the system can undo it:** use up what was added; replace what was removed; reduce a pressure increase by making fewer gas molecules.',
         '**Step 3 — State the direction:** “shifts to the right (forward)” or “to the left (backward)”.',
         '**Step 4 — State the result:** what happens to the amount of each substance, the colour, the yield.',
         '**Concentration:** add a reactant or remove a product → shifts **right**; add a product or remove a reactant → shifts **left**. Kc does **not** change.',
         '**Pressure (gases only):** count the **moles of gas** on each side. Increase pressure (decrease volume) → shift to the side with **fewer** gas moles; decrease pressure → side with **more** gas moles. Equal gas moles on both sides → **no shift**. Kc does not change.',
         '**Also remember:** raising the temperature shifts an equilibrium in the **endothermic** direction (this *does* change K); a catalyst does **not** shift the equilibrium — it only helps reach it faster.'),
    U1.SS('s01', 'Model: squeezing N₂O₄ ⇌ 2NO₂', 23, 'cm_press',
          [('a', 'Equilibrium', 'Colourless N₂O₄ and brown NO₂ in a gas syringe at equilibrium: 1 mol gas on the left, 2 mol gas on the right.'),
           ('b', 'Squeeze', 'Push the plunger in: half the volume, double the pressure. The gas looks darker at first (more crowded).'),
           ('c', 'New equilibrium', 'The system reduces the pressure by forming the side with **fewer gas molecules**: 2NO₂ → N₂O₄. Fewer particles, the colour fades a little — shifted **left**.')],
          'Slide to apply the stress and watch the response.'),
    U1.ST('s02', 'Model: adding N₂ to the ammonia equilibrium', 22, 'cm_conc',
          [('**N₂ is added**: its concentration jumps, then falls as some of it reacts — but it stays higher than before.', 'n2'),
           ('**H₂ is used up** with the extra N₂, so its concentration falls.', 'h2'),
           ('**More NH₃ forms**: the equilibrium has shifted to the **right**. Kc is the same at the new equilibrium.', 'nh3')]),
    U1.TB('t01', 'Effect of concentration (textbook p.23)', 23,
          ['Change', 'Shift', 'Example: N₂ + 3H₂ ⇌ 2NH₃'],
          [['Add reactant', 'right', 'add N₂ or H₂ → more NH₃'], ['Remove reactant', 'left', 'remove H₂ → NH₃ decomposes'],
           ['Add product', 'left', 'add NH₃ → more N₂ and H₂'], ['Remove product', 'right', 'liquefy and remove NH₃ → more NH₃ forms']]),
    U1.TB('t02', 'Effect of pressure: count the gas moles', 23,
          ['Reaction', 'Gas moles left → right', 'Increase pressure shifts', 'Decrease pressure shifts'],
          [['N₂ + 3H₂ ⇌ 2NH₃', '4 → 2', 'right', 'left'], ['2SO₂ + O₂ ⇌ 2SO₃', '3 → 2', 'right', 'left'],
           ['N₂O₄ ⇌ 2NO₂', '1 → 2', 'left', 'right'], ['H₂ + I₂ ⇌ 2HI', '2 → 2', 'no shift', 'no shift'],
           ['CaCO₃(s) ⇌ CaO(s) + CO₂(g)', '0 → 1', 'left', 'right']],
          'Only gases count — ignore solids and liquids when counting moles.'),
    U1.WK('w05', 'Worked example: why pressure shifts the ammonia equilibrium (using Q)', 23,
          'Show with Q why halving the volume of an equilibrium mixture of N₂ + 3H₂ ⇌ 2NH₃ shifts it to the right.',
          [r'At equilibrium \(Q = K = \dfrac{[\text{NH}_3]^2}{[\text{N}_2][\text{H}_2]^3}\).',
           'Halving the volume **doubles** every concentration at that instant.',
           r'New \(Q = \dfrac{(2[\text{NH}_3])^2}{(2[\text{N}_2])(2[\text{H}_2])^3} = \dfrac{4}{16}K = \dfrac{K}{4}\)',
           'Q < K → the reaction goes forward (right) until Q rises back to K — more NH₃, fewer gas molecules, lower pressure.'],
          'Q drops to K/4, so the equilibrium shifts right.'),
    U1.WK('w06', 'Worked example: predicting shifts', 23,
          'Predict the shift: (a) adding H₂ to H₂(g) + I₂(g) ⇌ 2HI(g); (b) increasing pressure on the same system; (c) removing O₂ from 2SO₂ + O₂ ⇌ 2SO₃; (d) decreasing pressure on PCl₅(g) ⇌ PCl₃(g) + Cl₂(g).',
          ['(a) A reactant is added → the system uses it up → shifts **right**; more HI, less I₂ (the purple colour fades).',
           '(b) 2 gas moles on each side → **no shift** (pressure has no effect).',
           '(c) A reactant is removed → the system replaces it → shifts **left**; SO₃ decomposes.',
           '(d) Lower pressure → side with **more** gas moles (1 → 2) → shifts **right**; more PCl₃ and Cl₂.'],
          '(a) right; (b) no shift; (c) left; (d) right.'),
    U1.WK('w07', 'Worked example: colour changes', 22,
          'Yellow chromate turns orange dichromate in acid: 2CrO₄²⁻(aq) + 2H⁺(aq) ⇌ Cr₂O₇²⁻(aq) + H₂O(l). What colour do you see when (a) acid is added, (b) NaOH is added?',
          ['(a) More H⁺ (a reactant) → shift **right** → more orange Cr₂O₇²⁻ → the solution turns **orange**.',
           '(b) OH⁻ removes H⁺ (H⁺ + OH⁻ → H₂O) → a reactant is removed → shift **left** → more yellow CrO₄²⁻ → **yellow**.'],
          '(a) orange; (b) yellow.'),
    U1.MN('m01', 'Memory trick', 22, '**“The system is stubborn — it always does the opposite.”** Add something → it uses it up. Take something away → it makes more. Squeeze it → it makes fewer gas molecules.'),
    U1.CK('k03', 23, 'Increasing the pressure on 2SO₂(g) + O₂(g) ⇌ 2SO₃(g) will …',
          ['shift it left', 'shift it right', 'not affect it', 'change Kc'], 'B',
          '3 gas moles on the left, 2 on the right: higher pressure favours fewer moles → right.'),
    U1.CK('k04', 23, 'Pressure has no effect on the position of which equilibrium?',
          ['N₂ + 3H₂ ⇌ 2NH₃', 'N₂O₄ ⇌ 2NO₂', 'H₂ + Cl₂ ⇌ 2HCl', '2SO₂ + O₂ ⇌ 2SO₃'], 'C',
          'H₂ + Cl₂ ⇌ 2HCl has 2 gas moles on each side, so changing pressure cannot reduce the number of molecules.'),
    U1.CK('k05', 22, 'Ammonia is removed from N₂ + 3H₂ ⇌ 2NH₃ as it forms. The effect is …',
          ['less NH₃ forms', 'the equilibrium shifts right and the yield increases', 'Kc increases', 'nothing happens'], 'B',
          'Removing a product makes the system replace it → shift right → higher yield. Kc stays the same at constant temperature.'),
    U1.RM('r01', 'Tips and common mistakes', 23,
          'Concentration and pressure changes move the **position**, not the **value** of K. Only temperature changes K.',
          'Count only **gas** moles for pressure questions.',
          'A catalyst never shifts an equilibrium.',
          'Use the full phrase in answers: “the equilibrium shifts to the right to oppose the increase in …”.'),
]

U1.M('q1', L1, 19, 'For H₂(g) + I₂(g) ⇌ 2HI(g) at equilibrium, [H₂] = [I₂] = 0.10 M and [HI] = 0.70 M. Kc = …', ['7.0', '49', '70', '0.020'], 'B',
     ['Step 1: Kc = [HI]² / ([H₂][I₂]).', 'Step 2: = 0.49 / 0.010 = 49.'],
     'Square [HI] because its coefficient is 2.', [('What is Kc for the reverse reaction 2HI ⇌ H₂ + I₂?', '1/49 ≈ 0.020.'), ('If Kc is large, are reactants or products favoured?', 'Products.')])
U1.S('q2', L1, 20, 'For a reaction Kc = 4.0. A mixture has Qc = 10. In which direction will the reaction proceed? Explain.', 'To the left (backward), because Qc > Kc: there is too much product.',
     ['Step 1: compare Q with K: 10 > 4.0.', 'Step 2: Q > K means the ratio products/reactants is too large.', 'Step 3: the backward reaction is faster until Q falls to 4.0.'],
     'Q < K → right; Q > K → left.', [('Qc = 1.0 and Kc = 4.0: which way?', 'To the right.'), ('What is true when Qc = Kc?', 'The system is at equilibrium.')])
